#include <iostream>
#include <numeric>
#include <string>
#include <vector>

int totalScore(const std::vector<std::string>& ops) {
    std::vector<int> scores;
    for (const std::string& op : ops) {
        if (op == "+") {
            scores.push_back(scores[scores.size() - 1] + scores[scores.size() - 2]);
        } else if (op == "D") {
            scores.push_back(scores.back() * 2);
        } else if (op == "C") {
            scores.pop_back();
        } else {
            scores.push_back(std::stoi(op));
        }
    }
    return std::accumulate(scores.begin(), scores.end(), 0);
}

int main() {
    int n;
    std::cin >> n;
    std::vector<std::string> ops(n);
    for (int i = 0; i < n; i++) {
        std::cin >> ops[i];
    }
    std::cout << totalScore(ops) << "\n";
    return 0;
}

