import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Main {
    static int totalScore(String[] ops) {
        Deque<Integer> scores = new ArrayDeque<>();
        for (String op : ops) {
            if (op.equals("+")) {
                // Take the top off to reach the score under it, then put it back.
                int last = scores.pop();
                int sum = last + scores.peek();
                scores.push(last);
                scores.push(sum);
            } else if (op.equals("D")) {
                scores.push(scores.peek() * 2);
            } else if (op.equals("C")) {
                scores.pop();
            } else {
                scores.push(Integer.parseInt(op));
            }
        }
        int total = 0;
        for (int score : scores) {
            total += score;
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String[] ops = new String[n];
        for (int i = 0; i < n; i++) {
            ops[i] = in.next();
        }
        System.out.println(totalScore(ops));
    }
}

