package main

import (
	"fmt"
	"strconv"
)

func totalScore(ops []string) int {
	scores := []int{}
	for _, op := range ops {
		top := len(scores) - 1
		switch op {
		case "+":
			scores = append(scores, scores[top]+scores[top-1])
		case "D":
			scores = append(scores, scores[top]*2)
		case "C":
			scores = scores[:top]
		default:
			score, _ := strconv.Atoi(op)
			scores = append(scores, score)
		}
	}
	total := 0
	for _, score := range scores {
		total += score
	}
	return total
}

func main() {
	var n int
	fmt.Scan(&n)
	ops := make([]string, n)
	for i := range ops {
		fmt.Scan(&ops[i])
	}
	fmt.Println(totalScore(ops))
}

